    source_info::Union{SourceInfo,Nothing}
    # the struct's one constructor, tagged: dart's generative constructors are `SourceMapping._`,
    # `SourceMapping` and `SourceMapping.unmapped` (Julia has no named constructors), each an anchored
    # function below that makes the value through this one
    SourceMapping(::Val{:_}, instruction_offset::Int, source_info::Union{SourceInfo,Nothing}) = new(instruction_offset, source_info)
end

