@parity "wasm_builder/lib/source_map.dart:94 SourceMapSerializer.serializeAsJson" serialize_as_json(s::SourceMapSerializer)::@NamedTuple{version::Int, sources::Vector{String}, names::Vector{String}, mappings::String} = _source_map_to_json(s.mappings)

@parity "wasm_builder/lib/source_map.dart:97 _sourceMapToJson" function _source_map_to_json(mappings::Vector{SourceMapping})::@NamedTuple{version::Int, sources::Vector{String}, names::Vector{String}, mappings::String}
    # dart's Set literals keep insertion order; a Vector with a membership Dict does the same.
    sources_list = String[]
    source_indices = Dict{String,Int}()
    for mapping in mappings
        info = mapping.source_info
        if info !== nothing && !haskey(source_indices, info.file_uri)
            source_indices[info.file_uri] = length(sources_list)
            push!(sources_list, info.file_uri)
        end
    end

    names_list = String[]
    name_indices = Dict{String,Int}()
    for mapping in mappings
        info = mapping.source_info
        if info !== nothing && info.name !== nothing && !haskey(name_indices, info.name)
            name_indices[info.name] = length(names_list)
            push!(names_list, info.name)
        end
    end

    mappings_str = IOBuffer()

    last_target_column = 0
    last_source_index = 0
    last_source_line = 0
    last_source_column = 0
    last_name_index = 0

    first = true

    for i in eachindex(mappings)
        mapping = mappings[i]
        source_info = mapping.source_info

        if source_info === nothing && first
            # Initial parts of the code are unmapped by default and need no explicit unmapping;
            # binaryen cannot handle single-segment mappings at the beginning of the mappings.
            continue
        end

        first = false

        last_target_column = _encode_vlq(mappings_str, mapping.instruction_offset, last_target_column)

        if source_info !== nothing
            source_index = source_indices[source_info.file_uri]

            last_source_index = _encode_vlq(mappings_str, source_index, last_source_index)
            last_source_line = _encode_vlq(mappings_str, source_info.line, last_source_line)
            last_source_column = _encode_vlq(mappings_str, source_info.col, last_source_column)

            if source_info.name !== nothing
                name_index = name_indices[source_info.name]
                last_name_index = _encode_vlq(mappings_str, name_index, last_name_index)
            end
        end

        if i != lastindex(mappings)
            Base.write(mappings_str, ',')
        end
    end

    (version = 3, sources = sources_list, names = names_list, mappings = String(take!(mappings_str)))
end

"""Writes the VLQ of the delta between `value` and `offset` into `output` and returns `value`."""
@parity "wasm_builder/lib/source_map.dart:192 _encodeVLQ" function _encode_vlq(output::IOBuffer, value::Int, offset::Int)::Int
    delta = value - offset
    sign_bit = 0
    if delta < 0
        sign_bit = 1
        delta = -delta
    end
    delta = (delta << 1) | sign_bit
    while true
        digit = delta & _vlq_base_mask
        delta >>= _vlq_base_shift
        if delta > 0
            digit |= _vlq_continuation_bit
        end
        Base.write(output, _base64_digits[digit+1])
        delta > 0 || break
    end
    value
end

@parity "wasm_builder/lib/source_map.dart:211 _vlqBaseShift" const _vlq_base_shift = 5

@parity "wasm_builder/lib/source_map.dart:212 _vlqBaseMask" const _vlq_base_mask = (1 << 5) - 1

@parity "wasm_builder/lib/source_map.dart:213 _vlqContinuationBit" const _vlq_continuation_bit = 1 << 5

@parity "wasm_builder/lib/source_map.dart:214 _base64Digits" const _base64_digits = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
